+    // A plate with no type has no field, not a null.
+    CHECK_FALSE(workspace["plates"][1].contains("plateType"));
+    CHECK(first.find("null") == std::string::npos);
+    // Nothing changed, so the next turn sends the same bytes.
+    CHECK(block() == first);
